((newType) => {

    // each node type needs a nodeset, clone that too
    let nodeset = RED.nodes.registry.getNodeSetForType("debug");

    nodeset = JSON.parse(JSON.stringify(nodeset))

    nodeset.id = "node-red/" + newType
    nodeset.types = [newType]

    RED.nodes.registry.addNodeSet(nodeset)

    // unlink the object from the realDebug node
    let theRealDebug = RED.nodes.registry.getNodeType("debug")
    let obj = JSON.parse(JSON.stringify(RED.nodes.registry.getNodeType("debug")))

    // new default values go here.
    obj.defaults.complete.value = "payload"
    obj.defaults.statusType.value = "counter"
    obj.defaults.statusVal.value = ""
    obj.defaults.tostatus.value = true
    obj.defaults.console.value = false
    obj.defaults.tosidebar.value = false

    obj.category = 'alias node'

    // define a new type - not optimal
    obj.type = newType;

    // basic functionality required by the node before it
    // changes its type.
    obj.label = theRealDebug.label;
    obj.labelStyle = theRealDebug.labelStyle;
    obj.oneditprepare = theRealDebug.oneditprepare;
    obj.oneditsave = theRealDebug.oneditsave;
    obj.button = theRealDebug.button;

    obj.onadd = function() {
        // change the type back to the original type 
        // when node is added to the workspace 
        this.type = 'debug'; 
        theRealDebug.onadd.call(this);
    }

    RED.nodes.registry.registerNodeType(newType, obj)
})(msg.newTypeName);

